('WO-2026-00005', 'ten_lsp', 'FA-29497', 'open', 'critical', NULL, 'Fault reported on P-201 (opened by hand)', '', 'manual', 'North Yard', NULL, NULL, NULL, 'Tom Haddad', TIMESTAMP'2026-10-13 08:39:14', NULL, NULL, NULL),
('WO-2026-LSP01', 'ten_lsp', 'FA-31340', 'in_progress', 'high', 'HVAC-05', 'HVAC compressor replacement', 'Reported by operator; parts on order.', 'manual', 'North Yard', TIMESTAMP'2026-10-11 08:00:00', TIMESTAMP'2026-10-13 17:00:00', NULL, 'Shop', TIMESTAMP'2026-10-11 17:02:04', NULL, NULL, NULL),
