-- Fleet page data for Databricks, exported from transit_orchestrator (Postgres) 2026-10-13 09:09
-- CREATE OR REPLACE TABLE: safe to re-run; each run replaces these tables with this snapshot.
-- Other tables in the schema (e.g. audit_records) are not touched.

CREATE SCHEMA IF NOT EXISTS workspace.transit_orchestrator;

-- ===== tenants: agencies (MVT, LSP); every row is scoped by tenant_id =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.tenants (
  `id` STRING NOT NULL,
  `code` STRING NOT NULL,
  `name` STRING NOT NULL,
  `timezone` STRING NOT NULL,
  `agent_persona` STRING NOT NULL,
  `created_at` TIMESTAMP NOT NULL
) USING DELTA COMMENT 'agencies (MVT, LSP); every row is scoped by tenant_id. Primary key: id';

-- ===== canonical_entities: master vehicle list: Vehicle column (label) =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.canonical_entities (
  `id` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `entity_type` STRING NOT NULL,
  `label` STRING NOT NULL
) USING DELTA COMMENT 'master vehicle list: Vehicle column (label). Primary key: id. Rows: entity_type = \'vehicle\'';

-- ===== identity_crosswalk: vehicle ID in each product system (asset_mgmt, trip_mgmt, telematics, safety) =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.identity_crosswalk (
  `id` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `entity_type` STRING NOT NULL,
  `canonical_id` STRING NOT NULL,
  `system` STRING NOT NULL,
  `external_id` STRING NOT NULL
) USING DELTA COMMENT 'vehicle ID in each product system (asset_mgmt, trip_mgmt, telematics, safety). Primary key: id. Rows: entity_type = \'vehicle\'';

-- ===== am_assets: make/model/year, odometer, PM overdue, asset status =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.am_assets (
  `asset_number` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `unit_label` STRING NOT NULL,
  `make` STRING NOT NULL,
  `model` STRING NOT NULL,
  `year` INT NOT NULL,
  `vin` STRING NOT NULL,
  `odometer` INT NOT NULL,
  `last_pm_date` DATE NOT NULL,
  `last_pm_odometer` INT NOT NULL,
  `pm_interval_miles` INT NOT NULL,
  `status` STRING NOT NULL,
  `depot` STRING NOT NULL
) USING DELTA COMMENT 'make/model/year, odometer, PM overdue, asset status. Primary key: asset_number';

-- ===== am_work_orders: Maintenance column: open work orders =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.am_work_orders (
  `id` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `asset_number` STRING NOT NULL,
  `status` STRING NOT NULL,
  `priority` STRING NOT NULL,
  `fault_code` STRING,
  `title` STRING NOT NULL,
  `description` STRING NOT NULL,
  `source` STRING NOT NULL,
  `shop_depot` STRING,
  `shop_start` TIMESTAMP,
  `shop_end` TIMESTAMP,
  `external_ref` STRING,
  `created_by` STRING NOT NULL,
  `created_at` TIMESTAMP NOT NULL,
  `closed_at` TIMESTAMP,
  `closed_by` STRING,
  `resolution` STRING
) USING DELTA COMMENT 'Maintenance column: open work orders. Primary key: id';

-- ===== tm_vehicles: Type, seats, wheelchair positions, Depot, base schedule status =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.tm_vehicles (
  `vehicle_code` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `label` STRING NOT NULL,
  `vehicle_type` STRING NOT NULL,
  `capacity` INT NOT NULL,
  `wheelchair_positions` INT NOT NULL,
  `depot` STRING NOT NULL,
  `status` STRING NOT NULL
) USING DELTA COMMENT 'Type, seats, wheelchair positions, Depot, base schedule status. Primary key: vehicle_code';

-- ===== tm_availability_blocks: Schedule column: unavailable until / reason =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.tm_availability_blocks (
  `id` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `vehicle_code` STRING NOT NULL,
  `start` TIMESTAMP NOT NULL,
  `end` TIMESTAMP NOT NULL,
  `reason` STRING NOT NULL,
  `source_ref` STRING,
  `active` BOOLEAN NOT NULL,
  `created_at` TIMESTAMP NOT NULL
) USING DELTA COMMENT 'Schedule column: unavailable until / reason. Primary key: id';

-- ===== tm_runs: Runs today column =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.tm_runs (
  `id` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `service_date` DATE NOT NULL,
  `route_name` STRING NOT NULL,
  `block_name` STRING NOT NULL,
  `start_time` TIMESTAMP NOT NULL,
  `end_time` TIMESTAMP NOT NULL,
  `vehicle_code` STRING,
  `driver_code` STRING,
  `status` STRING NOT NULL,
  `original_vehicle_code` STRING,
  `original_driver_code` STRING,
  `reassigned` BOOLEAN NOT NULL,
  `reassignment_ref` STRING,
  `delay_minutes` INT NOT NULL
) USING DELTA COMMENT 'Runs today column. Primary key: id';

-- ===== tl_devices: telematics device per vehicle =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.tl_devices (
  `device_id` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `firmware` STRING NOT NULL,
  `online` BOOLEAN NOT NULL
) USING DELTA COMMENT 'telematics device per vehicle. Primary key: device_id';

-- ===== tl_readings: Telemetry column: engine temp, oil pressure, fault codes (latest reading) =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.tl_readings (
  `id` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `device_id` STRING NOT NULL,
  `ts` TIMESTAMP NOT NULL,
  `engine_temp_c` DOUBLE NOT NULL,
  `oil_pressure_kpa` DOUBLE NOT NULL,
  `battery_v` DOUBLE NOT NULL,
  `speed_kph` DOUBLE NOT NULL,
  `odometer` INT NOT NULL,
  `dtc_codes` STRING NOT NULL
) USING DELTA COMMENT 'Telemetry column: engine temp, oil pressure, fault codes (latest reading). Primary key: id';

-- ===== sf_defects: Maintenance column: open safety defects =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.sf_defects (
  `id` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `vehicle_ref` STRING NOT NULL,
  `category` STRING NOT NULL,
  `severity` STRING NOT NULL,
  `description` STRING NOT NULL,
  `status` STRING NOT NULL,
  `out_of_service` BOOLEAN NOT NULL,
  `source` STRING NOT NULL,
  `external_ref` STRING,
  `work_order_id` STRING,
  `created_by` STRING NOT NULL,
  `created_at` TIMESTAMP NOT NULL,
  `closed_at` TIMESTAMP,
  `closed_by` STRING,
  `resolution` STRING
) USING DELTA COMMENT 'Maintenance column: open safety defects. Primary key: id';

-- ===== workflows: Orchestration column: active workflow and current step =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.workflows (
  `id` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `workflow_type` STRING NOT NULL,
  `status` STRING NOT NULL,
  `current_step` STRING,
  `vehicle_id` STRING,
  `vehicle_label` STRING,
  `trigger_event_id` STRING NOT NULL,
  `trigger_type` STRING NOT NULL,
  `severity` STRING,
  `title` STRING NOT NULL,
  `summary` STRING NOT NULL,
  `steps` STRING NOT NULL,
  `context` STRING NOT NULL,
  `trace_id` STRING NOT NULL,
  `detected_at` TIMESTAMP NOT NULL,
  `work_order_opened_at` TIMESTAMP,
  `pulled_at` TIMESTAMP,
  `returned_at` TIMESTAMP,
  `human_touches` INT NOT NULL,
  `runs_at_risk` INT NOT NULL,
  `runs_covered` INT NOT NULL,
  `started_at` TIMESTAMP NOT NULL,
  `updated_at` TIMESTAMP NOT NULL,
  `completed_at` TIMESTAMP
) USING DELTA COMMENT 'Orchestration column: active workflow and current step. Primary key: id';

